cir = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 13), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 52000000)).clone(2400)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cir.setStatus('mandatory')
if mibBuilder.loadTexts: cir.setDescription('The default value is 2400\n\t  cir defines committed information rate\n\t  cir is in bits per second\n\t  Maximum value for cir for an E1 card is 2048000 and\n\t  for a T1 card is 1536000.\n\t  cir has to be less than or equal to the port speed.\n\t  Maximum value for cir for an E3 card is 34368000, for\n\t  a T3 card is 44736000m, and for HSSI it is 52000000.\n\t  Note that for FRSM-2CT3 card, the peak value of\n\t  permissible CIR is 1536000.\n\t  Maximum value for FRSM-HS2B-12IN1 is 10240000\n\t  Any value from 1 to 2399 will be rounded off to 2400.\n\t  For FRSM12 Card:\n\t  The range is 0-44736000 bps for T3, and\n\t  The range is 0-34368000 bps for E3.\n\t  cir can be 0 only for chanServType of uBR.\n        ')
bc = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 14), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 2097151)).clone(5100)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: bc.setStatus('mandatory')
if mibBuilder.loadTexts: bc.setDescription('The default value is 5100\n\t bc defines burst committed.  bc is in bytes.\n\t bc can not be 0 when cir is not 0.\n\t bc has to be 0 if cir is 0.\n\t The peak value for bc in FRSM-VHS cards is (2^21 -1),\n\t i.e. 2097151 and for all other cards, it is 65535.\n\t For FRSM-VHS cards, the relation between CIR and Bc should \n\t be such that Tc is always less than 512 seconds. \n\t For FRSM12 Card: \n\t The range is 0-2097151\n        ')
be = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 15), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 2097151)).clone(5100)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: be.setStatus('mandatory')
if mibBuilder.loadTexts: be.setDescription('The default value is 5100 be defines the burst excess.\n     \t     be can not be 0 when cir is 0.  be is in bytes.\n\t     The peak value for be in FRSM-VHS cards is (2^21 -1),\n\t\t i.e. 2097151 and for all other cards, it is 65535.\n\t\t For FRSM-VHS cards, setting the value of 2091751 will \n\t\t cause the policing to be disabled.\n\t\t For FRSM12 Card: \n\t\t The range is 0-2097151\n\t\t')
ibs = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 16), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 2097151)).clone(100)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: ibs.setStatus('mandatory')
if mibBuilder.loadTexts: ibs.setDescription('The default value is 100\n\t ibs should be less or equal to bc when cir is greater\n\t than 0. ibs has to be 0 when cir is 0.\n\t The peak value for ibs in FRSM-VHS cards is (2^21 -1),\n\t i.e. 2097151 and for all other cards, it is 65535.\n\n\t For FRSM12 Card: Not Supported\n        ')
foreSightEnable = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 17), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('disable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: foreSightEnable.setStatus('mandatory')
if mibBuilder.loadTexts: foreSightEnable.setDescription('The default value is 2\n\t  This variable sets foreSight option\n\t  Note that when you enable foresight option then you can\n\t  modify qir, mir and pir, otherwise you CAN NOT change\n\t  these values if you are disabling foresight or if foresight\n\t  option is already disabled.\n\t  The RATE CONTROL FEATURE has to be ON in order to enable \n\t  foresight and also modify its parameter. \n\t  enable = 1\n\t  disable = 2\n\n\t For FRSM12 Card: Not Supported\n        ')
qir = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 18), Integer32().subtype(subtypeSpec=ValueRangeConstraint(160, 6400000)).clone(160)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: qir.setStatus('mandatory')
if mibBuilder.loadTexts: qir.setDescription('The dafault is 160\n\t qir is defined in fastpackets/sec and it defines\n\t quiescent information rate for Foresight.  1 cell/sec\n\t is equal to 16 fastpackets/sec.\n\t Following information about cps is for reference only: \n\t The peak value for qir in FRSM-VHS cards is 285714 cps and\n\t for all other cards, it is 10000 cps.\n\t For FRSM-VHS cards, cell will be the ATM cell (48 byte payload).\n\n\t For FRSM12 Card: Not Supported\n        ')
mir = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 19), Integer32().subtype(subtypeSpec=ValueRangeConstraint(160, 6400000)).clone(160)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: mir.setStatus('mandatory')
if mibBuilder.loadTexts: mir.setDescription('The dafault is 160\n\t mir is defined in fastpackets/sec and it defines\n\t minimum information rate for Foresight.  1 cell/sec \n\t is equal to 16 fastpackets/sec.\n\t Following information about cps is for reference only: \n\t The peak value for qir in FRSM-VHS cards is 285714 cps and\n\t for all other cards, it is 10000 cps.\n\t For FRSM-VHS cards, cell will be the ATM cell (48 byte payload).\n\n\t For FRSM12 Card: Not Supported\n        ')
pir = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 20), Integer32().subtype(subtypeSpec=ValueRangeConstraint(160, 6400000)).clone(160)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: pir.setStatus('mandatory')
if mibBuilder.loadTexts: pir.setDescription('The dafault is 160\n\t pir is defined in fastpackets/sec and it defines\n\t peak information rate for Foresight.  1 cell/sec\n\t is equal to 16 fastpackets/sec.\n\t Following information about cps is for reference only: \n\t The peak value for qir in FRSM-VHS cards is 285714 cps and\n\t for all other cards, it is 10000 cps.\n\t For FRSM-VHS cards, cell will be the ATM cell (48 byte payload).\n\n\t For FRSM12 Card: Not Supported\n        ')
chanLocRmtLpbkState = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 21), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('disable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanLocRmtLpbkState.setStatus('mandatory')
if mibBuilder.loadTexts: chanLocRmtLpbkState.setDescription('The default is disable.\n\t This variable enables or disables the remote loopback for each\n\t channel.\n\t When you enable this option on a connection (channel) then all the\n\t cells that are coming from the network side would be looped back\n\t toward the network and all the frames coming from the user side\n\t would be dropped.\n\t This channel remote loopback has nothing to do with the chanTestType\n\t option, each one does a different function. \n\t For example, the channel remote loopback is used for looping the data\n\t toward the network and if this connection is terminated on an IPX\n\t then they can put a test equipment and measure some of the \n\t characteristics of the network.\n\t1 = enable\n\t2 = disable\n\n\t For FRSM12 Card: Not Supported\n        ')
chanTestType = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 22), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3))).clone(namedValues=NamedValues(("testcon", 1), ("testdelay", 2), ("notest", 3))).clone('notest')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanTestType.setStatus('mandatory')
if mibBuilder.loadTexts: chanTestType.setDescription('The default is notest.\n\t The chanTestType starts testing the continuity or delay of a connection.\n\t It sends specific cell patterns toward the network and the terminating\n\t end of this connection has to be an AXIS or ASI of a BPX in order for \n\t this test to be working. \n\t The receiving node would loop back when it receives these\n\t cells. The test should be done in about couple of seconds. The testcon\n\t tests the continuity of the connection and testdelay uses the same\n\t test except that it measures for delay through the network. \n\t To test the delay follow this procedure:\n\t\ta- set chanTestType to testdelay\n\t\tb- read chanTestState till it is Pass or Fail \n\t\tc- Read chanRTDResult for the delay if it is Pass\n\t\t*Note that the chanTestType would go back to notest when the\n\t\t test is completed \n\t To test the continuity follow this procedure:\n\t\ta- set chanTestType to testcon\n\t\tb- read chanTestState till it is Pass or Fail \n\t\t*Note that the chanTestType would go back to notest when the\n\t\t test is completed \n\t You CAN NOT select 2 tests back to back, you have selcelt one and wait \n\t the result and then start the other one.\n    SYNTAX  \n\t When you select testdelay \n\t \n\t This is the type of the test\n\t 1 = Test Continuity\n\t 2 = Test Delay\n\t 3 = No Test\n        ')
chanTestState = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 23), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))).clone(namedValues=NamedValues(("passed", 1), ("failed", 2), ("inprogress", 3), ("notinprogress", 4))).clone('notinprogress')).setMaxAccess("readonly")
if mibBuilder.loadTexts: chanTestState.setStatus('mandatory')
if mibBuilder.loadTexts: chanTestState.setDescription('This shows the state of the test\n\t When you add a connection then the chanTestState becomes notinprogress\n\t and when you select any test, it would go to inprogress state and after\n\t it completes the test, it will go to failed or passed state.\n\t 1 = Passed\n\t 2 = Failed\n\t 3 = In Progress \n\t 4 = Not In Progress\n        ')
chanRTDResult = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 24), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 65535)).clone(65535)).setMaxAccess("readonly")
if mibBuilder.loadTexts: chanRTDResult.setStatus('mandatory')
if mibBuilder.loadTexts: chanRTDResult.setDescription('This is round trip delay in milliseconds.\n\t When you select testdelay option for the chanTestType, the result of\n\t the test that is measured in milliseconds can be read in chanRTDResult.\n        ')
chanType = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 25), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6))).clone(namedValues=NamedValues(("frNIW", 1), ("frSIW-transparent", 2), ("frSIW-translate", 3), ("frFUNI", 4), ("frForward", 5), ("frNIWReplace", 6)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanType.setStatus('mandatory')
if mibBuilder.loadTexts: chanType.setDescription('sets channel type\n                 Type 1 is frame-relay network interworking (NIW-unicast)\n                 type 2 is service interworking with out any SDU translation\n                 type 3 is service interworking with SDU translation\n                 type 4 is frame-relay UNI, currently mode-1a which is ALL5\n                 type 5 is frame forwarding\n                 types 1,2,3 and 5 are supported as explained above \n                 type 4 (frame-relay UNI) is NOT supported\n                 type 6 is also supported. It  means frame-relay Network\n                 Interworking with DLCI in FRSSCS-PDU always set to 1022\n                 For FRSM12 Card: frFUNI is not supported.\n                ')
chanFECNconfig = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 26), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("mapEFCI", 1), ("setEFCIzero", 2)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanFECNconfig.setStatus('mandatory')
if mibBuilder.loadTexts: chanFECNconfig.setDescription('sets FECN config mapEFCI valid only for SIW \n                 The FECN bits in frame-relay are mapped to EFCI bit in the ATM\n                 cells.\n\t\t')
chanDEtoCLPmap = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 27), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3))).clone(namedValues=NamedValues(("mapCLP", 1), ("setCLPzero", 2), ("setCLPone", 3)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanDEtoCLPmap.setStatus('mandatory')
if mibBuilder.loadTexts: chanDEtoCLPmap.setDescription('sets mapping of CLP bit \n                 The DE bit is mapped to CLP bit in ATM cell\n                 in Case 2 and 3, the DE bit is ignored and CLP bit\n                 is set to a constant value\n                 For FRSM12 Card:\n                 Should not be mapCLP for chanType of frForward.\n\t\t')
chanCLPtoDEmap = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 28), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))).clone(namedValues=NamedValues(("mapDE", 1), ("setDEzero", 2), ("setDEone", 3), ("ignoreCLP", 4)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanCLPtoDEmap.setStatus('mandatory')
if mibBuilder.loadTexts: chanCLPtoDEmap.setDescription('sets mapping of DE bit 1,2,3 valid for SIW\n                 1,4 valid for NIW\n                 The CLP bit is mapped to DE bit in frame-relay\n                 in the Case of 2 and 3, the CLP bit is ignored and DE bit\n                 is set to a constant value\n                 ignoreCLP ignores CLP bit and DE bit remains as received.\n                 For FRSM12 Card:\n                 Should be ignoreCLP for chanType of frForward.\n                 Should not be setDEzero/setDEone for chanType of frNIW \n                    and frNIWReplace.\n                 Should not be ignoreCLP for chanType of frSIW-transparent\n                    and frSIW-translate.\n\t\t')
chanIngrPercentUtil = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 29), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 100)).clone(100)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanIngrPercentUtil.setStatus('mandatory')
if mibBuilder.loadTexts: chanIngrPercentUtil.setDescription('the channel ingress utilized percentage\n\t\t\t\t')
chanEgrPercentUtil = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 30), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 100)).clone(100)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanEgrPercentUtil.setStatus('mandatory')
if mibBuilder.loadTexts: chanEgrPercentUtil.setDescription('the channel egress utilized percentage\n\t\t\t\t')
chanEgrSrvRate = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 31), Integer32().subtype(subtypeSpec=ValueRangeConstraint(2400, 52000000)).clone(2400)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanEgrSrvRate.setStatus('mandatory')
if mibBuilder.loadTexts: chanEgrSrvRate.setDescription('The channel egress cir.\n\t Maximum value for chanEgrSrvRate for an E1 card is 2048000 and\n\t for a T1 card is 1536000.\n\t chanEgrSrvRate has to be less than or equal to the port speed.\n\t Maximum value for chanEgrSrvRate for an E3 card is 34368000, for\n\t a T3 card is 44736000m, and for HSSI it is 52000000.\n\t Note that for FRSM-2CT3 card, the peak value of\n\t permissible chanEgrSrvRate is 1536000.\n\t For FRSM12 Card:\n\t This object is used only for CAC and the range will be same\n\t as the range for cir object. The Maximum value is 44736000m.\n\t')
chanOvrSubOvrRide = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 32), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("disable", 1), ("enable", 2))).clone('disable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanOvrSubOvrRide.setStatus('mandatory')
if mibBuilder.loadTexts: chanOvrSubOvrRide.setDescription('This MIB variable allows one to add a new connection on a port\n\t\t even if it is over subscribed.\n\n\t\t For FRSM12 Card: Not Supported\n\t\t')
chanFrConnType = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 33), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6))).clone(namedValues=NamedValues(("pvc", 1), ("svc", 2), ("spvc", 3), ("par", 4), ("pnni", 5), ("tag", 6))).clone('pvc')).setMaxAccess("readwrite")
