chanServType = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 55), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6, 7, 8, 9))).clone(namedValues=NamedValues(("highpriority", 1), ("rtVBR", 2), ("nrtVBR", 3), ("aBR", 4), ("uBR", 5), ("queue6", 6), ("queue7", 7), ("queue8", 8), ("stdABR", 9)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanServType.setStatus('mandatory')
if mibBuilder.loadTexts: chanServType.setDescription('This indicates the class of the connection\n\t\t1-High priority (typically CBR connections)\n\t\t2- real-time VBR\n\t\t3- non-real time VBR\n\t\t4- Available Bit Rate\n\t\t5- Unspecified Bit Rate\n\t\t9- Standard ABR\n\t\tThere are 8 queues actually but only 4 are currently being used\n\t\t(the 4 queues are for CBR, VBR-rt, <VBR-nrt and ABR>, UBR traffic).\n\t\tThis object is currently suuported only in FRSM-VHS and FRSM-8T1E1.\n\t\tFor FRSM-8T1E1, a 0 indicates that the connections are of old model\n\t\ttype where chanServType object is unused.\n\t\tNote that chanServType is not modifiable after a channel has been\n\t\tenabled\n\t\tFor FRSM12 Card:\n\t\tThe types aBR, queue6, queue7, queue8 are not supported\n\t\t')
chanServiceRateOverride = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 56), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('disable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanServiceRateOverride.setStatus('mandatory')
if mibBuilder.loadTexts: chanServiceRateOverride.setDescription('This variable sets the SAR IR programming option.\n\t\tForesight and chanServiceRateOverride are mutually exclusive.\n\t\t\n\t\tFor FRSM12 Card: Not Supported\n\t\t')
chanServiceRate = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 57), Integer32().subtype(subtypeSpec=ValueRangeConstraint(160, 6400000))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanServiceRate.setStatus('mandatory')
if mibBuilder.loadTexts: chanServiceRate.setDescription('This is the rate to which IR can be set to when \n\t\tchanServiceRateOverride is set to enabled. If chanServiceRateOverride\n\t\tis disabled then this object does not have any significance.\n\t\tFor FRSM-8P, this is defined in fastpackets/sec.\n\t\tFor FRSM-VHS, this is defined in atm cells per second.\n\t\tFor VHS the range in cells per second will be 10 to 400000 cps.\n\t\t\n\t\tFor FRSM12 Card: Not Supported\n\t\t')
zeroCirConEir = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 58), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 52000000)).clone(0)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: zeroCirConEir.setStatus('mandatory')
if mibBuilder.loadTexts: zeroCirConEir.setDescription("zeroCirConEir defines EIR value for '0' CIR connection. \n\t\tIf zeroCirConEir is '0', EIR is set to port speed. If zeroCirConEir \n\t\tis non-zero value, EIR is set to value of this object, and this value \n\t\tis used for policing in ingress direction. \n\t\tThis object is valid only for a zero cir connection.\n\t\tzeroCirConEir has to be less than or equal to the port speed.")
chanReroute = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 59), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("true", 1), ("false", 2))).clone('false')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: chanReroute.setStatus('mandatory')
if mibBuilder.loadTexts: chanReroute.setDescription(' This is used by the administrator to trigger the re-routing\n         of the connection. The rerouting takes effect, when this object\n         is set to true(1). When set to false (2), no action is taken.\n         A get on this object always returns false (2).\n         This object is not applicable to MGX Release 1.x.\n       ')
frConnSCR = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 60), Integer32()).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frConnSCR.setStatus('mandatory')
if mibBuilder.loadTexts: frConnSCR.setDescription(' Sustained cell rate, Used for VBR connections setup with PNNI\n          controller.\n          For FRSM12 Card: Default value is frConnPCR\n          This object is not applicable to MGX Release 1.x\n        ')
frConnRemoteSCR = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 61), Integer32()).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frConnRemoteSCR.setStatus('mandatory')
if mibBuilder.loadTexts: frConnRemoteSCR.setDescription(' Sustained cell rate of the other end,  Used for VBR connections\n          setup with PNNI controller.\n          For FRSM12 Card: Default value is frConnSCR\n          This object is not applicable to MGX Release 1.x\n        ')
frConnTemplateId = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 62), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 17)).clone(17)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frConnTemplateId.setStatus('mandatory')
if mibBuilder.loadTexts: frConnTemplateId.setDescription('This object specifies the template identifier for the connection\n         template associated with this connection.\n         The valid range for templates is 1..16.\n         A value of 17 indicates no template is associated with this\n         connection\n         For FRSM12 Card: Not Supported\n         This object is not applicable to MGX Release 1.x\n        ')
frConnAdminStatus = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 63), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("up", 1), ("down", 2))).clone('down')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frConnAdminStatus.setStatus('mandatory')
if mibBuilder.loadTexts: frConnAdminStatus.setDescription('This object specifies channel admin status. \n         This object is not applicable to MGX Release 1.x.\n         ')
frChanCnfChangeCount = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 64), Counter32()).setMaxAccess("readonly")
if mibBuilder.loadTexts: frChanCnfChangeCount.setStatus('mandatory')
if mibBuilder.loadTexts: frChanCnfChangeCount.setDescription('\n        This object is added only for FRSM12 card.\n\n        This counter tracks the number of configuration changes\n\t\tthat happen on a channel. The  counter is\n\t\tassociated only with the end point  and NOT with the\n\t\tconnection itself.\n\n\t\tThis counter is used by the NMS to determine if a connection\n\t\tconfiguration had been modified and requires an upload.\n\t\tThis functionality is conventionally achieved by time \n\t\tstamping using a time-of-day clock. However, in switches\n\t\twhere time-of-day clock is not available, the following\n\t\tscheme is used:\n\n\t\tThe upload counter is incremented, when:\n\n\t\t* assignment of connection to an end point channel. This\n\t\t  happens when a connection is added and assigned this \n\t\t  channel number.\n\t\t* de-assignment of connection from a channel number. This\n\t\t  happens when a connection is deleted and the \n\t\t  end point  resource is released.\n\t\t* When there is a configuration change done to the connection\n\t\t  that is associated with this end point channel number.\n\n\t\tIn a new system, an unutilised resouce (channel number)\n\t\thas a counter value of zero. When a connection is added to\n\t\tthis channel end point, the counter is incremented. And is\n\t\tincremented for any of the above operations. When a connection\n\t\tis deleted the value of this counter is incremented and\n\t\tpreserved till a new connection gets associated with this\n\t\tchannel end point.\n        \n        This object is not applicable to MGX Release 1.x.')
frChanCnfIgnoreIncomingDE = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 65), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frChanCnfIgnoreIncomingDE.setStatus('mandatory')
if mibBuilder.loadTexts: frChanCnfIgnoreIncomingDE.setDescription('  \n         This object is added for FRSM12 card.\n\n         When this object is enabled, the incoming frames with \n         DE(Discard Eligible) bit set to 1 are counted in the \n         Bc bucket instead of Be bucket\n \n         This object is not applicable to MGX Release 1.x.\n        ')
frChanOamCCEnable = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 66), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('disable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frChanOamCCEnable.setStatus('mandatory')
if mibBuilder.loadTexts: frChanOamCCEnable.setDescription('\n        This object is added for FRSM12 card.\n\n\t\tThis object serves to enable or disable continuity check(CC)\n\t\ton a connection endpoint. When continuity check is enabled \n\t\ton an endpoint, the endpoint anticipates OAM CC cells from its\n\t\tpeer endpoint. OAM CC cells are sent when the peer endpoint\n\t\tdoes not have traffic cells to send. If the connection is\n\t\tidle and this endpoint has not received OAM CC cells for a \n\t\tperiod of 3.5 +/- 0.5 seconds, it declares continuity failure.\n\n\t\tThis object serves to administratively control the CC feature.\n\t\tTypical implementations (of this feature) may choose to ignore\n\t\tthis control or impose other conditions to actually enable CC \n\t\tcell flow. However, if this object is set to false(2), then this \n\t\tfeature should be disabled\n    \n        This object is not applicable to MGX Release 1.x.\n        ')
frChanStatsEnable = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 67), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('disable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frChanStatsEnable.setStatus('mandatory')
if mibBuilder.loadTexts: frChanStatsEnable.setDescription('\n        This object is added for FRSM12 card.\n\n        Limits imposed by software or hardware implementations\n        could restrict the amount of statistical data that can be\n        maintained in a physical entity (like a service module card).\n        Hence there could be a need to restrict statistics collection\n        to a smaller subset.\n\n        This object serves the purpose of enabling/disabling statistics\n        collection on a per connection basis. In implementations which\n        do not have such limitations, this object can be set to enable(1)\n        for all connections\n \n        This object is not applicable to MGX Release 1.x.\n        ')
frChanLocalLpbkEnable = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 68), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('disable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frChanLocalLpbkEnable.setStatus('mandatory')
if mibBuilder.loadTexts: frChanLocalLpbkEnable.setDescription('\n        This object is added for FRSM12 card.\n\n        This object when enabled adds a channel-level loopback\n        towards the port side.  If the connection is in loopback,\n        Connection MIB (FrChanCnfGrpEntry) variables cannot be modified.\n\n        This object is not applicable to MGX Release 1.x.\n        ')
frChanUpcEnable = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 69), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2))).clone('enable')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frChanUpcEnable.setStatus('mandatory')
if mibBuilder.loadTexts: frChanUpcEnable.setDescription('\n        This object is added for FRSM12 card.\n\n        This object when disabled, disables Frame Relay policing.\n\n        This object is not applicable to MGX Release 1.x.\n        ')
frChanSlaveType = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 70), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("persistentSlave", 1), ("nonPersistentSlave", 2))).clone('persistentSlave')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frChanSlaveType.setStatus('mandatory')
if mibBuilder.loadTexts: frChanSlaveType.setDescription("\n        This object is added for FRSM12 card.\n        This object indicates whether a master endpoint has a persistent\n        slave or not. A connection with a master and a non-persistent\n        slave is considered a single-ended SPVC.\n\n        This object is only meaningful when 'frMastership'\n        contains the value of 'master(1)'. And this variable \n        must be used with 'frMastership' to decide\n        if a connection is single-ended or not.\n\n        This object is not applicable to MGX Release 1.x.\n        ")
frConnRemoteMBS = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 1, 1, 71), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 5000000)).clone(1024)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frConnRemoteMBS.setStatus('mandatory')
if mibBuilder.loadTexts: frConnRemoteMBS.setDescription("Remote Maximum Burst Size in terms of number of cells.\n         This object should be set by the user in cases when\n         the remote end of the connection is an ATM end-point\n         where the Local MBS can be explicitly specified. In such\n         cases, this element should be set to be equal to the\n         remote end-point's local MBS.\n\n         This object is not applicable to MGX Release 1.x.\n         ")
chanNumNextAvailable = MibScalar((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 2), Integer32().subtype(subtypeSpec=ValueRangeConstraint(16, 4015))).setMaxAccess("readonly")
if mibBuilder.loadTexts: chanNumNextAvailable.setStatus('mandatory')
if mibBuilder.loadTexts: chanNumNextAvailable.setDescription("This variable contains the next UNUSED channel number\n\t\t of the possible 4000 (ranging from 16 to 4015).\n\t\t This number can be used in channel config table, the \n\t\t ChanNumNextAvailable gets updated if the number gets\n\t\t used to create a logical channel.  \n\t\t A '0' indicates that no more channels are available.\n\n\t\t For FRSM12 Card: Not Supported\n\t\t")
frstdABRCnfGrpTable = MibTable((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 3), ).setMaxAccess("notaccessible")
if mibBuilder.loadTexts: frstdABRCnfGrpTable.setStatus('mandatory')
if mibBuilder.loadTexts: frstdABRCnfGrpTable.setDescription('The ABR config table is for logical channel interface\n\t\t (upto 4000 entries). The actual number of entries\n\t\t supported by a card depends on the type of card.\n\t\t eg: FRSM-4T1/E1 supports 256 entries\n\t\t     FRSM-8T1/E1 supports 1000 entries\n\t\t     FRSM-T3/E3/HS2/T3B/E3B/HS2B-HSSI supports 2000 entries\n\t\t     FRSM-2CT3/HS2B-12IN1 supports 4000 entries\n\t\t     FRSM12 supports 16000 entries\n\t\t')
frstdABRCnfGrpEntry = MibTableRow((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 3, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "CISCO-WAN-AXIPOP-MIB", "frstdABRcnfChanNum"))
if mibBuilder.loadTexts: frstdABRCnfGrpEntry.setStatus('mandatory')
if mibBuilder.loadTexts: frstdABRCnfGrpEntry.setDescription(' An entry for logical channel\n\t\t')
frstdABRcnfChanNum = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 3, 1, 1), Integer32()).setMaxAccess("readonly")
if mibBuilder.loadTexts: frstdABRcnfChanNum.setStatus('mandatory')
if mibBuilder.loadTexts: frstdABRcnfChanNum.setDescription('Refers to the virtual connection index\n\t\t Note that the actual range of the index\n\t\t supported by a card depends on the type of card.\n\t\t eg: FRSM-4T1/E1 supports a range from 16..271 (256 entries)\n\t\t     FRSM-8T1/E1 supports a range from 16..1015 (1000 entries)\n\t\t     FRSM-T3/E3/HS2/T3B/E3B/HS2B-HSSI supports a range from\n\t\t     16..2015 (2000 entries)\n\t\t     FRSM-2CT3/HS2B-12IN1 supports a range from 16..4015 (4000 entries)\n\t\t     For FRSM12 Card:\n\t\t     Byte 3 = Chassis Number, Byte 2 = Slot Number,\n\t\t     Byte 1 & 0 = channel Number.\n\t\t     Lower two bytes range from 16..16015 (16000 entries)\n\t\t')
frstdABRTBE = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 3, 1, 2), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 16777215)).clone(16777215)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: frstdABRTBE.setStatus('mandatory')
if mibBuilder.loadTexts: frstdABRTBE.setDescription('Transient Buffer Exposure. The unit is number of cells.')
frstdABRFRTT = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 1, 2, 1, 3, 1, 3), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 16700)).clone(0)).setMaxAccess("readwrite")
