if mibBuilder.loadTexts: x21LineInterfaceType.setDescription(' This object indicates serial interface type.\n         Default is hssi.\n\t\t \n\t\t This object is not is configurable in FRSM-HS2\n\t\t and FRSM-HS2B-HSSI. It will be set hssi by\n\t\t default for these cards\n\t\t \n\t\t This object is configurable in FRSM-H2B-12IN1.\n\t\t Default is v35')
x21ClkFrequencyThreshold = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 5, 1, 1, 1, 11), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 5)).clone(3)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: x21ClkFrequencyThreshold.setStatus('mandatory')
if mibBuilder.loadTexts: x21ClkFrequencyThreshold.setDescription('This object indicates user configurable percentage of\n          clock frequency, which is used by DTE clock monitoring\n          to declare clock rate out of bound alarm. This object\n          is valid only for X.21/v.35/HSSI DTE interfaces.\n\t\t  This object is supported by FRSM-HS2 and FRSM-HS2/B')
serialLineRate = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 5, 1, 1, 1, 12), Integer32().subtype(subtypeSpec=ValueRangeConstraint(48000, 51840000))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: serialLineRate.setStatus('mandatory')
