if mibBuilder.loadTexts: bearerCid.setStatus('mandatory')
if mibBuilder.loadTexts: bearerCid.setDescription('This attribute defines the CID (Channel ID associated with this \n\t bearer connection.This refers to the same value as \n         vismAal2CidNum in the vismAal2CidCnfTable.\n        ')
bearerLcn = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 5, 5, 9, 1, 1, 3), Integer32().subtype(subtypeSpec=ValueRangeConstraint(131, 510))).setMaxAccess("readonly")
